        "id": "madhya-pradesh-story-1",
        "title": "The Ultimate Guide to Khajuraho, Madhya Pradesh",
        "category": "Travel Guide",
        "shortDescription": "Discover the hidden secrets and local tips for exploring Khajuraho. A complete itinerary and what to expect on your trip to Madhya Pradesh.",
        "heroImage": "https://picsum.photos/seed/khajuraho/800/600",
        "author": {
          "name": "Ravi Sharma",
          "role": "Local Expert & Guide for Madhya Pradesh",
          "image": "/India/Gallery/images Guide 2.jpg"
        },
        "date": "Sep 10, 2026",
        "sections": [
          {
            "heading": "Story of Khajuraho",
            "content": "Khajuraho holds a rich history deeply intertwined with the cultural fabric of Madhya Pradesh. From ancient folklore passed down through generations to modern-day vibrant traditions, every street and monument has a tale to tell. As you walk through its bustling markets and serene landscapes, you can feel the echoes of the past blending seamlessly with the energy of the present. Many travelers find that understanding the history of Khajuraho makes their visit infinitely more rewarding."
          },
          {
            "heading": "Trips & Itineraries in Khajuraho",
            "content": "Planning your trip to Khajuraho is an exciting endeavor. Whether you are seeking a quick weekend getaway or a comprehensive week-long expedition, there are numerous options. We recommend starting your day early to catch the stunning sunrise over the local landmarks, followed by a guided heritage walk. In the afternoon, dive into the culinary scene, and reserve your evenings for cultural performances or relaxing walks. We offer customized 3-day and 5-day trips that cover all major attractions without feeling rushed."
          },
          {
            "heading": "Guide Person Details",
            "content": "Your journey through Khajuraho will be led by Ravi Sharma, our highly experienced local expert. Born and raised in Madhya Pradesh, Ravi Sharma possesses an intimate knowledge of the hidden gems and local secrets that typical tourist guides often overlook. With over a decade of experience in hosting travelers, Ravi Sharma ensures your safety, comfort, and an incredibly enriching cultural immersion. You will hear fascinating anecdotes, interact with local artisans, and truly experience Khajuraho like a local.",
            "guideImage": "/India/Gallery/images Guide 2.jpg"
          }
        ]
